script:
/* Write your CSS here */
.logo-slider {
    overflow: hidden;
    width: 100%;
    position: relative;
}

.logo-track {
    display: flex;
    align-items: center;
    gap: 40px;
    width: max-content;
}

.logo-track .logo-item {
    flex-shrink: 0;
}
.testimonial-slider {
    overflow: hidden;
    position: relative;
    width: 100%;
}

.testimonial-track {
    display: flex;
    transition: transform 0.5s ease;
    width: 100%;
}

.testimonial-slide {
    min-width: 100%;
    box-sizing: border-box;
}

.testimonial-prev,
.testimonial-next {
    cursor: pointer;
}
